from pathlib import Path
import base64,gzip,hashlib
p=Path("index.html")
s=p.read_text(encoding="utf-8")
css=gzip.decompress(base64.b64decode("")).decode("utf-8")
proof=gzip.decompress(base64.b64decode("H4sIAKuLd2oC/1XOsQrCQAyA4d2nCLcf9wLXbAqCaJGic6wpDaR3JanFx1cUB5d/+ZYf8l1W6JXcmzDWieNstQ4ByISi0o21CafjFrrzvoVLtYVFOWD2mQpmwZwED7IytMbinNMXPt0pP2PHNkn5h+ujeD8OogvbD9J7BDcvP2Rng5AAAAA=")).decode("utf-8")
repls=[
("ONE TRIP V5.27 – Mobile Premium Travel App","ONE TRIP V5.28 – Signature Premium Travel App"),
("V5.27","V5.28"),
('content="5.27"','content="5.28"'),
("BUILD 5.27","BUILD 5.28"),
]
for old,new in repls:
    if old not in s: raise SystemExit(f"Missing V5.28 patch anchor: {old}")
    s=s.replace(old,new)
if s.count("</style>\n")!=1: raise SystemExit("Unexpected </style> count")
s=s.replace("</style>\n",css+"</style>\n",1)
anchor=' <div class="content"><div class="section-head"><h2>Inspiration für dich</h2>'
if s.count(anchor)!=1: raise SystemExit("Home proof anchor mismatch")
s=s.replace(anchor,proof+anchor,1)
p.write_text(s,encoding="utf-8")
sha=hashlib.sha256(p.read_bytes()).hexdigest()
expected="9a3e15d3e1fc952110112e0d3f640d7908842474e2413fc874bcd1c4d7f58fa4"
if sha!=expected: raise SystemExit(f"V5.28 verification failed: {sha} != {expected}")
print("ONE TRIP V5.28 built and verified",sha)
